//! Boot splash: the opening screen between the boot log and the desktop.
//!
//! The boot first prints its log as usual. As soon as `/disk` is mounted (it
//! holds `SPLASH.BMP`, generated by `bzimage/build.rs` from
//! `assets/splash/splash.jpg`) the kernel calls [`start`]: from then on
//!
//! * the framebuffer console no longer draws (log lines still go to serial),
//!   so nothing scrolls across the screen;
//! * `framebuffer::present` from the window manager and the boot-demo apps is
//!   held back, so the desktop does not flash up half-way through the boot;
//! * every `MILESTONE:` line moves the progress bar, and the latest log line
//!   is shown as the status underneath it.
//!
//! [`finish`] (first thing in `desktop::run`) fills the bar and hands the
//! screen to the desktop. A panic calls [`abort`] so its message is visible.
//!
//! The image, title, tagline, footer and bar track are composed once into
//! `base`; a redraw only copies `base` and draws the bar fill + status line.
//! Redraws happen inside `_print`, so they must never allocate or block:
//! the state is behind `try_lock` and the status text is a fixed buffer.

use crate::gfx::{rgb, Canvas, Color, TextStyle};
use alloc::vec::Vec;
use core::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
use spin::Mutex;

static ACTIVE: AtomicBool = AtomicBool::new(false);
static COUNT: AtomicUsize = AtomicUsize::new(0);
static EXPECTED: AtomicUsize = AtomicUsize::new(1);
static STARTED_NS: AtomicU64 = AtomicU64::new(0);
static STATE: Mutex<Option<State>> = Mutex::new(None);
/// Redraws and the time they took (reported at the end: the splash must not
/// slow the boot down).
static DRAWS: AtomicU64 = AtomicU64::new(0);
static DRAW_NS: AtomicU64 = AtomicU64::new(0);

/// Non-milestone log lines redraw the status at most this often.
const LINE_REDRAW_NS: u64 = 1_000_000_000;
const STATUS_MAX: usize = 96;

const TEXT: Color = rgb(0xEA, 0xF5, 0xEC);
const DIM: Color = rgb(0xA6, 0xC4, 0xB0);
const LEAF: Color = rgb(0x7C, 0xC4, 0xA4);
const LEAF_LIGHT: Color = rgb(0xC8, 0xF0, 0xD6);
const TRACK: Color = rgb(0x0B, 0x1F, 0x17);

struct State {
    w: usize,
    h: usize,
    /// The composed screen; a redraw paints the bar + status into it.
    base: Vec<u32>,
    /// Clean copy of the rows the bar and status cover (restored before each
    /// redraw) -- one full-screen buffer plus this strip, not two full ones:
    /// the PC kernel heap (32 MiB) ran out late in the boot with two.
    strip: Vec<u32>,
    strip_y: usize,
    /// The whole screen was presented once; later redraws send only the strip.
    shown: bool,
    bar: (i32, i32, i32, i32),
    status: [u8; STATUS_MAX],
    status_len: usize,
    last_ns: u64,
    image: bool,
}

/// True while the splash owns the screen.
pub fn active() -> bool {
    ACTIVE.load(Ordering::Acquire)
}

/// Show the splash. `expected` = how many milestones this boot prints from
/// here on (the bar's 100 %; it stops at 96 % until [`finish`]).
pub fn start(expected: usize) {
    crate::gfx::warm_glyphs();
    if active() {
        return;
    }
    let Some((w, h)) = crate::framebuffer::dimensions() else { return };
    if w < 320 || h < 240 {
        return;
    }
    let (mut base, image) = match load_image(w, h) {
        Some(px) => (px, true),
        None => (fallback(w, h), false),
    };
    let bar = compose_base(&mut base, w, h);
    // rows from the glow above the bar to below the status line
    let strip_y = (bar.1 - 8).max(0) as usize;
    let strip_end = ((bar.1 + bar.3 + 40) as usize).min(h);
    let strip = base[strip_y * w..strip_end * w].to_vec();
    let mut st = State { w, h, base, strip, strip_y, shown: false, bar, status: [0; STATUS_MAX], status_len: 0, last_ns: 0, image };
    set_status(&mut st, b"Menyiapkan sistem");
    // The last boot's count (written by `finish`) beats the built-in guess:
    // the same medium on the same machine prints the same milestones.
    let expected = remembered().unwrap_or(expected);
    EXPECTED.store(expected.max(1), Ordering::Relaxed);
    COUNT.store(0, Ordering::Relaxed);
    STARTED_NS.store(crate::arch::cpu::nanos(), Ordering::Relaxed);
    *STATE.lock() = Some(st);
    crate::println!(
        "[splash] boot splash on screen ({}x{}, {}; {} milestones expected) -- log continues on serial",
        w,
        h,
        if image { "SPLASH.BMP" } else { "no image, gradient" },
        expected
    );
    ACTIVE.store(true, Ordering::Release);
    redraw(true);
}

/// Fill the bar, show "ready" and release the screen to the desktop.
pub fn finish() {
    if !active() {
        return;
    }
    let image = {
        let mut guard = STATE.lock();
        let image = guard.as_ref().map_or(false, |s| s.image);
        if let Some(st) = guard.as_mut() {
            set_status(st, b"Siap -- membuka desktop");
            draw(st, 1000);
        }
        image
    };
    ACTIVE.store(false, Ordering::Release);
    *STATE.lock() = None; // free the buffers
    remember(COUNT.load(Ordering::Relaxed));
    let secs = crate::arch::cpu::nanos().saturating_sub(STARTED_NS.load(Ordering::Relaxed)) / 1_000_000_000;
    crate::println!(
        "[kernel] MILESTONE: BOOT SPLASH OK ({} milestones under the splash in ~{} s, {} redraws took {} ms, {}; desktop takes over)",
        COUNT.load(Ordering::Relaxed),
        secs,
        DRAWS.load(Ordering::Relaxed),
        DRAW_NS.load(Ordering::Relaxed) / 1_000_000,
        if image { "image from /disk/SPLASH.BMP" } else { "gradient fallback" }
    );
}

const PROGRESS_FILE: &str = "/disk/BOOTPROG.TXT";

/// Milestone count of the previous boot from this disk, if sane.
fn remembered() -> Option<usize> {
    let bytes = crate::vfs::read(PROGRESS_FILE).ok()?;
    let n = core::str::from_utf8(&bytes).ok()?.trim().parse::<usize>().ok()?;
    (5..=500).contains(&n).then_some(n)
}

fn remember(n: usize) {
    if n >= 5 && remembered() != Some(n) {
        let s = alloc::format!("{}\r\n", n);
        let _ = crate::vfs::write(PROGRESS_FILE, s.as_bytes());
    }
}

/// Give the screen back to the console at once (panic path: no locks, no
/// allocation).
pub fn abort() {
    ACTIVE.store(false, Ordering::Release);
}

/// A kernel log line arrived while the splash is up (called by `_print`).
pub fn note(line: &str) {
    let line = line.trim();
    if line.is_empty() || line.starts_with("[splash]") {
        return;
    }
    let milestone = line.find("MILESTONE: ").map(|i| &line[i + 11..]);
    if milestone.is_some() {
        COUNT.fetch_add(1, Ordering::Relaxed);
    }
    let Some(mut guard) = STATE.try_lock() else { return };
    let Some(st) = guard.as_mut() else { return };
    let now = crate::arch::cpu::nanos();
    match milestone {
        Some(m) => {
            let name = m.find(" OK").map_or(m, |i| &m[..i]);
            let mut buf = [0u8; STATUS_MAX];
            let n = copy_ascii(&mut buf, name.as_bytes());
            let n = n + copy_ascii(&mut buf[n..], b" siap");
            set_status(st, &buf[..n]);
        }
        None => {
            if now.saturating_sub(st.last_ns) < LINE_REDRAW_NS {
                return;
            }
            // Drop a leading "[tag] " -- the status reads like a sentence.
            let text = match (line.starts_with('['), line.find("] ")) {
                (true, Some(i)) => &line[i + 2..],
                _ => line,
            };
            set_status(st, text.as_bytes());
        }
    }
    st.last_ns = now;
    let permille = progress();
    draw(st, permille);
}

fn redraw(_force: bool) {
    if let Some(mut guard) = STATE.try_lock() {
        if let Some(st) = guard.as_mut() {
            let p = progress();
            draw(st, p);
        }
    }
}

fn progress() -> u32 {
    let (n, e) = (COUNT.load(Ordering::Relaxed), EXPECTED.load(Ordering::Relaxed));
    ((n * 1000 / e) as u32).min(960)
}

fn copy_ascii(dst: &mut [u8], src: &[u8]) -> usize {
    let mut n = 0;
    for &b in src {
        if n >= dst.len() {
            break;
        }
        dst[n] = if (0x20..0x7F).contains(&b) { b } else { b' ' };
        n += 1;
    }
    n
}

fn set_status(st: &mut State, text: &[u8]) {
    st.status_len = copy_ascii(&mut st.status, text);
}

/// Copy `base`, draw the bar fill, the status and the percentage, present.
fn draw(st: &mut State, permille: u32) {
    let t0 = crate::arch::cpu::nanos();
    draw_inner(st, permille);
    DRAWS.fetch_add(1, Ordering::Relaxed);
    DRAW_NS.fetch_add(crate::arch::cpu::nanos().saturating_sub(t0), Ordering::Relaxed);
}

fn draw_inner(st: &mut State, permille: u32) {
    // Before the first present `base` is the whole screen; after it, only the
    // strip rows (the full buffer is freed: the PC kernel heap needs the room).
    let (oy, rows) = if st.shown { (st.strip_y as i32, st.strip.len() / st.w) } else { (0, st.h) };
    let off = if st.shown { 0 } else { st.strip_y * st.w };
    st.base[off..off + st.strip.len()].copy_from_slice(&st.strip);
    let (bx, by, bw, bh) = st.bar;
    let by = by - oy; // canvas coordinates
    {
        let mut c = Canvas::new(&mut st.base, st.w, rows);
        let fill = (bw as i64 * permille as i64 / 1000) as i32;
        if fill > 0 {
            // A soft glow under the filled part, then the leaf gradient.
            for g in [2, 4] {
                let a = if g == 2 { 40 } else { 18 };
                pill(&mut c, bx - g, by - g, fill + 2 * g, bh + 2 * g, LEAF, a);
            }
            pill_gradient(&mut c, bx, by, fill.max(bh), bh, LEAF, LEAF_LIGHT);
        }
        let status = core::str::from_utf8(&st.status[..st.status_len]).unwrap_or("");
        let pct = permille / 10;
        let mut num = [0u8; 4];
        let mut n = 0;
        if pct >= 100 {
            num[n] = b'1';
            n += 1;
        }
        if pct >= 10 {
            num[n] = b'0' + ((pct / 10) % 10) as u8;
            n += 1;
        }
        num[n] = b'0' + (pct % 10) as u8;
        num[n + 1] = b'%';
        let pct_s = core::str::from_utf8(&num[..n + 2]).unwrap_or("");
        let pw = crate::gfx::text_width(pct_s, TextStyle::Strong);
        let ty = by + bh + 14;
        shadow_text(&mut c, bx, ty, status, DIM, bx + bw - pw - 16, TextStyle::Body);
        shadow_text(&mut c, bx + bw - pw, ty, pct_s, TEXT, bx + bw + 1, TextStyle::Strong);
    }
    if st.shown {
        crate::framebuffer::present_splash_rows(&st.base, st.strip_y, st.strip_y + rows);
    } else {
        crate::framebuffer::present_splash(&st.base);
        st.shown = true;
        st.base = st.strip.clone(); // keep only the strip from now on
    }
}

/// Read `/disk/SPLASH.BMP` and scale it to cover the screen (center crop).
fn load_image(w: usize, h: usize) -> Option<Vec<u32>> {
    let bytes = crate::vfs::read("/disk/SPLASH.BMP").ok()?;
    let (sw, sh, px) = crate::wallpaper::decode_bmp(&bytes).ok()?;
    drop(bytes);
    let (sw, sh, w, h) = (sw as usize, sh as usize, w as i64, h as i64);
    // Largest source rectangle with the screen's aspect ratio.
    let (cw, ch) = if sw as i64 * h > sh as i64 * w {
        ((sh as i64 * w / h) as usize, sh)
    } else {
        (sw, (sw as i64 * h / w) as usize)
    };
    let (x0, y0) = ((sw - cw) / 2, (sh - ch) / 2);
    let crop = if (cw, ch) == (sw, sh) {
        px
    } else {
        let mut v = Vec::with_capacity(cw * ch);
        for y in 0..ch {
            v.extend_from_slice(&px[(y0 + y) * sw + x0..(y0 + y) * sw + x0 + cw]);
        }
        v
    };
    Some(crate::wallpaper::resample(&crop, cw as i32, ch as i32, w as i32, h as i32))
}

/// No image on this boot medium: a deep forest gradient.
fn fallback(w: usize, h: usize) -> Vec<u32> {
    let mut v = alloc::vec![0u32; w * h];
    let mut c = Canvas::new(&mut v, w, h);
    c.fill_gradient(rgb(0x14, 0x3A, 0x2A), rgb(0x04, 0x10, 0x0B));
    v
}

/// Darken for legibility and paint everything that does not change: title,
/// tagline, footer and the bar track. Returns the bar rectangle.
fn compose_base(px: &mut [u32], w: usize, h: usize) -> (i32, i32, i32, i32) {
    // Vignette: dim everything a little, the lower part (text) more.
    for y in 0..h {
        let t = (y * 256 / h) as u32;
        let k = if t < 128 { 200 } else { 200 - (t - 128) * 110 / 128 }; // /256
        let row = &mut px[y * w..(y + 1) * w];
        for (x, p) in row.iter_mut().enumerate() {
            // Horizontal vignette: the outer eighth on each side darker.
            let edge = (x.min(w - 1 - x) * 8 * 256 / w).min(256) as u32;
            let k = k * (192 + edge / 4) / 256;
            let r = ((*p >> 16) & 0xFF) * k / 256;
            let g = ((*p >> 8) & 0xFF) * k / 256;
            let b = (*p & 0xFF) * k / 256;
            *p = (r << 16) | (g << 8) | b;
        }
    }
    let (wi, hi) = (w as i32, h as i32);
    let mut c = Canvas::new(px, w, h);

    // Title: BUITENZORG, wide-tracked, scaled up from the 24 px bold face.
    let scale = if w >= 1200 { 3 } else { 2 };
    let tracking = 5 * scale;
    let title = "BUITENZORG";
    let tw = c.text_width_scaled(title, TextStyle::Heading, scale, tracking);
    let th = crate::gfx::line_height(TextStyle::Heading) * scale;
    let ty = hi * 36 / 100 - th / 2;
    c.draw_text_scaled((wi - tw) / 2 + 2, ty + 3, title, rgb(0, 0, 0), TextStyle::Heading, scale, tracking, 140);
    c.draw_text_scaled((wi - tw) / 2, ty, title, TEXT, TextStyle::Heading, scale, tracking, 255);

    // A thin leaf rule, fading out at both ends.
    let ry = ty + th + 14;
    let rw = (tw / 3).max(80);
    for i in 0..rw {
        let d = (i - rw / 2).abs();
        let a = (230 - d * 460 / rw).clamp(0, 230) as u8;
        c.blend(((wi - rw) / 2 + i) as usize, ry as usize, LEAF, a);
        c.blend(((wi - rw) / 2 + i) as usize, (ry + 1) as usize, LEAF, a / 2);
    }

    let tag = "sistem operasi yang tumbuh dari Kebun Raya Bogor";
    let gw = c.text_width_scaled(tag, TextStyle::Body, 1, 1);
    let gy = ry + 14;
    c.draw_text_scaled((wi - gw) / 2 + 1, gy + 1, tag, rgb(0, 0, 0), TextStyle::Body, 1, 1, 150);
    c.draw_text_scaled((wi - gw) / 2, gy, tag, DIM, TextStyle::Body, 1, 1, 255);

    // Bar track.
    let bw = (wi * 42 / 100).clamp(240, 560);
    let bh = 6;
    let bx = (wi - bw) / 2;
    let by = hi * 78 / 100;
    pill(&mut c, bx - 1, by - 1, bw + 2, bh + 2, rgb(0x5A, 0x7A, 0x68), 90);
    pill(&mut c, bx, by, bw, bh, TRACK, 200);

    // Footer.
    let foot = "Gravicode Studios  -  dipimpin oleh Kang Fadhil";
    let fw = crate::gfx::text_width(foot, TextStyle::Body);
    shadow_text(&mut c, (wi - fw) / 2, hi - 34, foot, rgb(0x7E, 0x9C, 0x8A), wi, TextStyle::Body);
    (bx, by, bw, bh)
}

fn shadow_text(c: &mut Canvas, x: i32, y: i32, s: &str, color: Color, max_x: i32, style: TextStyle) {
    c.draw_text_styled(x + 1, y + 1, s, rgb(0, 0, 0), max_x + 1, style);
    c.draw_text_styled(x, y, s, color, max_x, style);
}

/// Coverage (0..=16) of a pill (rounded both ends, radius h/2) at a pixel,
/// 4x4 supersampled.
fn pill_cov(px: i32, py: i32, w: i32, h: i32) -> u32 {
    let r4 = h * 2; // radius in quarter pixels
    // the straight middle part is fully covered (only the ends are round)
    if px * 4 >= r4 && px * 4 + 3 <= w * 4 - r4 {
        return 16;
    }
    let mut n = 0;
    for sy in 0..4 {
        for sx in 0..4 {
            let (qx, qy) = (px * 4 + sx, py * 4 + sy);
            // a pill narrower than it is tall is a circle (clamp needs lo <= hi)
            let cx = qx.clamp(r4, (w * 4 - r4).max(r4));
            let (dx, dy) = (qx - cx, qy - r4);
            if dx * dx + dy * dy <= r4 * r4 {
                n += 1;
            }
        }
    }
    n
}

fn pill(c: &mut Canvas, x: i32, y: i32, w: i32, h: i32, color: Color, alpha: u8) {
    pill_with(c, x, y, w, h, alpha, |_| color);
}

fn pill_gradient(c: &mut Canvas, x: i32, y: i32, w: i32, h: i32, a: Color, b: Color) {
    let mix = |t: u8| {
        let ch = |s: u32| (((a >> s) & 0xFF) * (255 - t as u32) + ((b >> s) & 0xFF) * t as u32) / 255;
        (ch(16) << 16) | (ch(8) << 8) | ch(0)
    };
    pill_with(c, x, y, w, h, 255, mix);
}

/// `color(t)` with t = 0..=255 along the pill.
fn pill_with(c: &mut Canvas, x: i32, y: i32, w: i32, h: i32, alpha: u8, color: impl Fn(u8) -> Color) {
    if w <= 0 || h <= 0 {
        return;
    }
    for py in 0..h {
        for px in 0..w {
            let cov = pill_cov(px, py, w, h);
            if cov == 0 {
                continue;
            }
            let (gx, gy) = (x + px, y + py);
            if gx < 0 || gy < 0 || gx as usize >= c.width || gy as usize >= c.height {
                continue;
            }
            let a = (alpha as u32 * cov / 16) as u8;
            c.blend(gx as usize, gy as usize, color((px * 255 / w.max(1)) as u8), a);
        }
    }
}
